import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { FormArray, FormBuilder, FormsModule, ReactiveFormsModule, Validators } from '@angular/forms';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { MatButtonModule } from '@angular/material/button';
import { MatCardModule } from '@angular/material/card';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { MatSelectModule } from '@angular/material/select';
import { MatSnackBar, MatSnackBarModule } from '@angular/material/snack-bar';
import { API_ORIGIN, ApiService, Batch, CustomerDetail, Dashboard, Ingredient, RecipeDetail, RecipeSummary, SalesSummary } from '../core/api.service';
import { SearchSelectComponent } from '../shared/search-select.component';

const UI=[CommonModule,FormsModule,ReactiveFormsModule,RouterLink,MatButtonModule,MatCardModule,MatCheckboxModule,MatFormFieldModule,MatInputModule,MatProgressSpinnerModule,MatSelectModule,MatSnackBarModule,SearchSelectComponent];
const money=(n:number)=>new Intl.NumberFormat('es-UY',{style:'currency',currency:'UYU',maximumFractionDigits:2}).format(n||0);

@Component({standalone:true,imports:UI,template:`
<div class="title-row"><div><p class="eyebrow">RESUMEN GENERAL</p><h1>Tu negocio, en números claros</h1><p>Costos, nutrición y margen de todas tus recetas.</p></div><a mat-flat-button color="primary" routerLink="/recetas/nueva">Nueva receta</a></div>
<div *ngIf="!data" class="loading"><mat-spinner diameter="34"/> Cargando información…</div>
<ng-container *ngIf="data as d">
 <div class="metrics">
  <article><small>RECETAS ACTIVAS</small><strong>{{d.recipeCount}}</strong><em>{{d.ingredientCount}} ingredientes</em></article>
  <article><small>COSTO PROMEDIO</small><strong>{{currency(d.averageCost)}}</strong><em>por barra</em></article>
  <article><small>PRECIO PROMEDIO</small><strong>{{currency(d.averagePrice)}}</strong><em>venta directa</em></article>
  <article><small>MARGEN PROMEDIO</small><strong>{{d.averageMargin|number:'1.1-1'}}%</strong><em>margen bruto</em></article>
 </div>
 <div class="grid-2">
  <mat-card class="panel"><div class="panel-head"><div><h2>Rendimiento por receta</h2><p>Costo frente al precio de venta</p></div><a routerLink="/recetas">Ver todas</a></div>
   <div class="recipe-bars" *ngFor="let r of d.recipes"><div><b>{{r.name}}</b><span>{{currency(r.costPerBar)}} costo · {{currency(r.directPrice||0)}} venta</span></div><div class="bar-track"><i [style.width.%]="width(r.costPerBar,r.directPrice||1)"></i></div><strong>{{r.bestMargin|number:'1.0-1'}}%</strong></div>
  </mat-card>
  <mat-card class="panel"><div class="panel-head"><div><h2>Indicadores destacados</h2><p>Oportunidades de tu catálogo</p></div></div>
   <div class="highlights"><div><span>Más rentable<b>{{d.mostProfitable||'—'}}</b></span></div><div><span>Mayor proteína<b>{{d.highestProtein||'—'}}</b></span></div><div><span>Menos calorías<b>{{d.lowestCalories||'—'}}</b></span></div><div><span>Más costosa<b>{{d.mostExpensive||'—'}}</b></span></div></div>
  </mat-card>
 </div>
 <mat-card class="panel"><div class="panel-head"><div><h2>Recetas recientes</h2><p>Valores actuales recalculados desde los ingredientes</p></div></div>
  <div class="table-wrap"><table><thead><tr><th>RECETA</th><th>BARRAS</th><th>COSTO</th><th>PROTEÍNA</th><th>KCAL</th><th>MARGEN</th><th></th></tr></thead><tbody><tr *ngFor="let r of d.recipes"><td><a class="table-title" [routerLink]="['/recetas',r.id]">{{r.name}}</a><small>{{r.flavor}}</small></td><td>{{r.bars}}</td><td>{{currency(r.costPerBar)}}</td><td><b>{{r.proteinPerBar|number:'1.1-1'}} g</b></td><td>{{r.kcalPerBar|number:'1.0-0'}}</td><td><span class="pill" [class.warn]="r.bestMargin<30">{{r.bestMargin|number:'1.0-1'}}%</span></td><td><a mat-button [routerLink]="['/recetas',r.id]">Ver</a></td></tr></tbody></table></div>
 </mat-card>
</ng-container>`})
export class DashboardComponent implements OnInit {data?:Dashboard;currency=money;constructor(private api:ApiService){}ngOnInit(){this.api.dashboard().subscribe(x=>this.data=x)}width(cost:number,price:number){return Math.min(100,cost/price*100)}}

@Component({standalone:true,imports:UI,template:`
<div class="title-row"><div><p class="eyebrow">CATÁLOGO</p><h1>Ingredientes</h1><p>Actualizá un precio y todas tus recetas se recalculan.</p></div><div><a mat-button [href]="apiOrigin+'/api/ingredients/export.csv'">Descargar CSV</a><a mat-flat-button color="primary" routerLink="/ingredientes/nuevo">Nuevo ingrediente</a></div></div>
<mat-card class="panel"><div class="ingredient-filters"><mat-form-field appearance="outline"><mat-label>Nombre, marca o proveedor</mat-label><input matInput [(ngModel)]="search" [ngModelOptions]="{standalone:true}" placeholder="Buscar ingrediente..."></mat-form-field><app-search-select label="Categoría" [options]="categories" [value]="category" (valueChange)="category=$event"/><app-search-select label="Estado" [options]="statusOptions" valueKey="value" labelKey="label" [value]="status" (valueChange)="status=$event"/><app-search-select label="Uso en recetas" [options]="usageOptions" valueKey="value" labelKey="label" [value]="usage" (valueChange)="usage=$event"/><app-search-select label="Stock" [options]="stockOptions" valueKey="value" labelKey="label" [value]="stock" (valueChange)="stock=$event"/></div><div class="filter-summary"><span>{{filteredItems.length}} de {{items.length}} ingredientes</span><button mat-button type="button" (click)="clearFilters()">Limpiar filtros</button></div>
<div class="table-wrap"><table><thead><tr><th>INGREDIENTE</th><th>CATEGORÍA</th><th>USO</th><th>PRESENTACIÓN</th><th>PRECIO + IVA</th><th>COSTO BASE</th><th>STOCK</th><th></th></tr></thead><tbody><tr *ngFor="let x of filteredItems"><td><a class="table-title" [routerLink]="['/ingredientes',x.id]">{{x.name}}</a><small>{{x.brand||x.supplier||'Sin proveedor'}} · {{x.active?'Activo':'Inactivo'}}</small></td><td><span class="tag">{{x.category}}</span></td><td><b>{{x.activeRecipeCount}}</b><small>{{x.recipeCount}} recetas en total</small></td><td>{{x.packageQuantity}} {{x.purchaseUnit|lowercase}}</td><td><b>{{currency(x.grossPrice)}}</b><small>IVA {{x.vatPercent}}%</small></td><td>{{currency(x.costPerBaseUnit)}} / {{x.baseUnit|lowercase}}</td><td><span [class.stock-low]="x.stockCurrent<=x.stockMinimum">{{x.stockCurrent|number:'1.0-1'}} {{x.baseUnit|lowercase}}</span></td><td class="row-actions"><a mat-button [routerLink]="['/ingredientes',x.id]">Editar</a><button mat-button class="danger" type="button" (click)="remove(x)">Eliminar</button></td></tr></tbody></table><div class="empty" *ngIf="!filteredItems.length">No hay ingredientes que coincidan con los filtros.</div></div></mat-card>`})
export class IngredientsComponent implements OnInit {items:Ingredient[]=[];currency=money;apiOrigin=API_ORIGIN;search='';category='Todas';status='all';usage='all';stock='all';statusOptions=[{value:'all',label:'Todos'},{value:'active',label:'Activos'},{value:'inactive',label:'Inactivos'}];usageOptions=[{value:'all',label:'Todos'},{value:'active',label:'En recetas activas'},{value:'unused',label:'Sin usar en recetas'}];stockOptions=[{value:'all',label:'Todos'},{value:'low',label:'Stock bajo'},{value:'available',label:'Stock disponible'}];constructor(private api:ApiService,private snack:MatSnackBar){}ngOnInit(){this.load()}get categories(){return['Todas',...Array.from(new Set(this.items.map(x=>x.category))).sort((a,b)=>a.localeCompare(b,'es'))]}get filteredItems(){const q=this.normalize(this.search);return this.items.filter(x=>(!q||this.normalize(`${x.name} ${x.brand||''} ${x.supplier||''}`).includes(q))&&(this.category==='Todas'||x.category===this.category)&&(this.status==='all'||(this.status==='active'?x.active:!x.active))&&(this.usage==='all'||(this.usage==='active'?x.activeRecipeCount>0:x.recipeCount===0))&&(this.stock==='all'||(this.stock==='low'?x.stockCurrent<=x.stockMinimum:x.stockCurrent>x.stockMinimum)))}load(){this.api.ingredients('',true).subscribe(x=>this.items=x)}clearFilters(){this.search='';this.category='Todas';this.status='all';this.usage='all';this.stock='all'}remove(x:Ingredient){if(x.recipeCount>0){this.snack.open(`No se puede eliminar: está usado en ${x.recipeCount} receta(s). Podés marcarlo como inactivo.`,'Cerrar',{duration:4500});return}if(!window.confirm(`¿Eliminar definitivamente el ingrediente "${x.name}"?`))return;this.api.deleteIngredient(x.id).subscribe({next:()=>{this.items=this.items.filter(i=>i.id!==x.id);this.snack.open('Ingrediente eliminado','Cerrar',{duration:2500})},error:e=>this.snack.open(e.error?.title||'No se pudo eliminar','Cerrar',{duration:4500})})}private normalize(value:string){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase().trim()}}

@Component({standalone:true,imports:UI,template:`
<div class="title-row"><div><a class="back" routerLink="/ingredientes">Volver a ingredientes</a><h1>{{id?'Editar ingrediente':'Nuevo ingrediente'}}</h1><p>Compra, costo base e información por 100 g.</p></div><button mat-flat-button color="primary" (click)="save()" [disabled]="form.invalid||saving">Guardar cambios</button></div>
<form [formGroup]="form" class="form-grid">
 <mat-card class="panel span-2"><h2>Información general</h2><div class="fields cols-3"><mat-form-field appearance="outline"><mat-label>Nombre</mat-label><input matInput formControlName="name"></mat-form-field><mat-form-field appearance="outline"><mat-label>Categoría</mat-label><input matInput formControlName="category"></mat-form-field><mat-form-field appearance="outline"><mat-label>Marca</mat-label><input matInput formControlName="brand"></mat-form-field><mat-form-field appearance="outline"><mat-label>Proveedor</mat-label><input matInput formControlName="supplier"></mat-form-field><mat-form-field appearance="outline"><mat-label>Stock actual</mat-label><input matInput type="number" formControlName="stockCurrent"></mat-form-field><mat-form-field appearance="outline"><mat-label>Stock mínimo</mat-label><input matInput type="number" formControlName="stockMinimum"></mat-form-field></div><mat-checkbox formControlName="active">Ingrediente activo</mat-checkbox></mat-card>
 <mat-card class="panel"><h2>Compra y precio</h2><div class="fields"><mat-form-field appearance="outline"><mat-label>Cantidad envase</mat-label><input matInput type="number" formControlName="packageQuantity"></mat-form-field><app-search-select label="Unidad compra" [options]="units" formControlName="purchaseUnit"/><mat-form-field appearance="outline"><mat-label>Precio sin IVA</mat-label><input matInput type="number" formControlName="netPrice"></mat-form-field><mat-form-field appearance="outline"><mat-label>IVA %</mat-label><input matInput type="number" formControlName="vatPercent"></mat-form-field><app-search-select label="Unidad base" [options]="units" formControlName="baseUnit"/><mat-form-field appearance="outline"><mat-label>Densidad g/ml</mat-label><input matInput type="number" formControlName="densityGPerMl"></mat-form-field></div><div class="calc-preview">Precio con IVA <b>{{currency(gross)}}</b></div></mat-card>
 <mat-card class="panel" formGroupName="nutrition"><h2>Nutrición por 100 g</h2><div class="fields cols-2"><mat-form-field appearance="outline" *ngFor="let n of nutrients"><mat-label>{{n.label}}</mat-label><input matInput type="number" [formControlName]="n.key"></mat-form-field><mat-form-field appearance="outline"><mat-label>Fuente</mat-label><input matInput formControlName="source"></mat-form-field><app-search-select label="Tipo de fuente" [options]="sources" formControlName="sourceType"/></div></mat-card>
</form>`})
export class IngredientFormComponent implements OnInit {id='';saving=false;currency=money;units=['G','Kg','Ml','L','Unit'];sources=['Manufacturer','Estimated','External','Usda','Other'];nutrients=[{key:'kcal',label:'Calorías / kcal'},{key:'protein',label:'Proteínas g'},{key:'carbohydrates',label:'Carbohidratos g'},{key:'sugars',label:'Azúcares g'},{key:'fiber',label:'Fibra g'},{key:'totalFat',label:'Grasas totales g'},{key:'saturatedFat',label:'Saturadas g'},{key:'transFat',label:'Trans g'},{key:'sodiumMg',label:'Sodio mg'},{key:'cholesterolMg',label:'Colesterol mg'},{key:'polyols',label:'Polioles g'}];form=this.fb.group({name:['',Validators.required],category:['Otros',Validators.required],brand:[''],supplier:[''],purchaseUnit:['Kg'],packageQuantity:[1,[Validators.required,Validators.min(.0001)]],netPrice:[0,[Validators.required,Validators.min(0)]],vatPercent:[22],baseUnit:['G'],densityGPerMl:[null as number|null],notes:[''],active:[true],stockCurrent:[0],stockMinimum:[0],nutrition:this.fb.group({kcal:[0],protein:[0],carbohydrates:[0],sugars:[0],fiber:[0],totalFat:[0],saturatedFat:[0],transFat:[0],sodiumMg:[0],cholesterolMg:[0],polyols:[0],sourceType:['Manufacturer'],source:[''],sourceUrl:['']})});constructor(private fb:FormBuilder,private api:ApiService,private route:ActivatedRoute,private router:Router,private snack:MatSnackBar){}ngOnInit(){this.id=this.route.snapshot.paramMap.get('id')||'';if(this.id)this.api.ingredient(this.id).subscribe(x=>this.form.patchValue(x as any))}get gross(){return +(this.form.value.netPrice||0)*(1+(this.form.value.vatPercent||0)/100)}save(){if(this.form.invalid)return;this.saving=true;this.api.saveIngredient(this.form.getRawValue(),this.id||undefined).subscribe({next:()=>{this.snack.open('Ingrediente guardado','Cerrar',{duration:2500});this.router.navigate(['/ingredientes'])},error:e=>{this.saving=false;this.snack.open(e.error?.title||'No se pudo guardar','Cerrar')}})}}

@Component({standalone:true,imports:UI,template:`
<div class="title-row"><div><p class="eyebrow">FORMULACIONES</p><h1>Recetas</h1><p>Costos y macros siempre actualizados.</p></div><div><a mat-button [href]="apiOrigin+'/api/recipes/export.csv'">Descargar CSV</a><a mat-flat-button color="primary" routerLink="/recetas/nueva">Nueva receta</a></div></div>
<mat-card class="panel recipe-filters"><div><button mat-stroked-button type="button" *ngFor="let c of categories" [class.active-filter]="category===c" (click)="category=c">{{c}}</button></div><span>{{filteredGroups.length}} recetas</span></mat-card>
<div class="recipe-grid"><ng-container *ngFor="let g of filteredGroups"><mat-card class="recipe-card" *ngIf="selectedRecipe(g) as r"><div class="recipe-cover"><span>{{r.category}}</span><b>{{r.bars}} {{r.category==='Granolas'?'porciones':'barras'}}</b></div><div class="recipe-body"><h2>{{familyName(r.name)}}</h2><app-search-select class="recipe-version-select" *ngIf="g.versions.length>1" label="Versión" [options]="g.versionOptions" valueKey="id" labelKey="label" [value]="g.selectedId" (valueChange)="selectVersion(g,$event)"/><small class="single-version" *ngIf="g.versions.length===1">Versión única</small><div class="recipe-kpis"><span>Costo<strong>{{currency(r.costPerBar)}}</strong></span><span>Proteína<strong>{{r.proteinPerBar|number:'1.1-1'}} g</strong></span><span>Calorías<strong>{{r.kcalPerBar|number:'1.0-0'}}</strong></span></div><div class="margin"><span>Margen directo</span><b>{{r.bestMargin|number:'1.1-1'}}%</b></div><div class="actions"><a mat-button [routerLink]="['/recetas',r.id]">Ver análisis</a><a mat-button [routerLink]="['/recetas',r.id,'editar']">Editar</a></div></div></mat-card></ng-container></div>`})
export class RecipesComponent implements OnInit {items:RecipeSummary[]=[];groups:{key:string;category:string;versions:RecipeSummary[];versionOptions:{id:string;label:string}[];selectedId:string}[]=[];category='Todas';categories=['Todas','Barritas','Granolas'];currency=money;apiOrigin=API_ORIGIN;constructor(private api:ApiService){}ngOnInit(){this.api.recipes().subscribe(x=>{this.items=x.sort((a,b)=>a.name.localeCompare(b.name,'es'));const map=new Map<string,RecipeSummary[]>();for(const r of this.items){const key=this.familyName(r.name);map.set(key,[...(map.get(key)||[]),r])}this.groups=[...map.entries()].map(([key,versions])=>({key,category:versions[0].category,versions,selectedId:versions[0].id,versionOptions:versions.map(v=>({id:v.id,label:v.name.includes(' · ')?`${v.name.split(' · ')[1]} · ${v.targetWeightPerBar} g`:`Original · ${v.targetWeightPerBar} g`}))}))})}get filteredGroups(){return this.groups.filter(g=>this.category==='Todas'||g.category===this.category)}selectedRecipe(g:{versions:RecipeSummary[];selectedId:string}){return g.versions.find(v=>v.id===g.selectedId)||g.versions[0]}selectVersion(g:{selectedId:string},id:string){g.selectedId=id}familyName(name:string){return name.split(' · ')[0]}}

@Component({standalone:true,imports:UI,template:`
<div *ngIf="detail as d"><div class="title-row"><div><a class="back" routerLink="/recetas">Volver a recetas</a><h1>{{d.recipe.name}}</h1><p>{{d.recipe.description||d.recipe.flavor}}</p></div><div><button mat-stroked-button type="button" (click)="newVersion()">Nueva versión</button> <a mat-flat-button color="primary" [routerLink]="['/recetas',d.recipe.id,'editar']">Editar receta</a></div></div>
<mat-card class="panel version-panel"><div><b>Versiones</b><small>Cada versión conserva su propio peso, rendimiento, costos e ingredientes.</small></div><div class="version-list"><a mat-stroked-button *ngFor="let v of versions" [href]="'/recetas/'+v.id" [class.current-version]="v.id===d.recipe.id">{{versionLabel(v.name)}} · {{versionWeight(v)|number:'1.0-0'}} g</a></div></mat-card>
<div class="hero-kpis"><article class="primary"><small>COSTO POR BARRA</small><strong>{{currency(d.analysis.cost.perBar)}}</strong><span>{{currency(d.analysis.cost.total)}} por lote</span></article><article><small>PROTEÍNA</small><strong>{{d.analysis.perBar.protein|number:'1.1-1'}} g</strong><span>en una barra de {{d.recipe.targetWeightPerBar|number:'1.0-1'}} g</span></article><article><small>CALORÍAS</small><strong>{{d.analysis.perBar.kcal|number:'1.0-0'}}</strong><span>en {{d.recipe.targetWeightPerBar|number:'1.0-1'}} g</span></article><article><small>MARGEN GIMNASIO</small><strong>{{d.profitability.Gym?.marginPercent|number:'1.1-1'}}%</strong><span>{{currency(d.profitability.Gym?.profitPerUnit)}} ganancia</span></article></div>
<div class="alerts" *ngIf="d.alerts.length"><div *ngFor="let a of d.alerts">{{a}}</div></div>
<div class="grid-2"><mat-card class="panel"><div class="panel-head"><div><h2>Ingredientes</h2><p>{{d.analysis.theoreticalWeight|number:'1.0-1'}} g de peso teórico</p></div></div><div class="line" *ngFor="let x of d.analysis.contributions"><div><b>{{x.name}}</b><small>{{x.quantityBase|number:'1.0-2'}} g · {{x.protein|number:'1.1-1'}} g proteína</small></div><strong>{{currency(x.cost)}}</strong></div></mat-card>
<mat-card class="panel"><div class="panel-head"><div><h2>Composición del costo</h2><p>Lote completo</p></div></div><div class="cost-row" *ngFor="let x of costRows(d)"><span>{{x.label}}</span><div><i [style.width.%]="x.value/d.analysis.cost.total*100"></i></div><b>{{currency(x.value)}}</b></div><hr><div class="total"><span>Costo final</span><b>{{currency(d.analysis.cost.total)}}</b></div></mat-card></div>
<mat-card class="panel"><div class="panel-head"><div><h2>Información nutricional</h2><p>Por barrita de {{d.recipe.targetWeightPerBar|number:'1.0-1'}} g y por 100 g</p></div></div><div class="macro-grid"><div *ngFor="let n of macros"><small>{{n.label}}</small><b>{{d.analysis.perBar[n.key]|number:'1.1-1'}} {{n.unit}}</b><span>{{d.analysis.per100G[n.key]|number:'1.1-1'}} {{n.unit}} / 100 g</span></div></div></mat-card></div>`})
export class RecipeDetailComponent implements OnInit {detail?:RecipeDetail;versions:RecipeSummary[]=[];currency=money;macros=[{key:'protein',label:'Proteína',unit:'g'},{key:'carbohydrates',label:'Carbohidratos',unit:'g'},{key:'sugars',label:'Azúcares',unit:'g'},{key:'fiber',label:'Fibra',unit:'g'},{key:'totalFat',label:'Grasas',unit:'g'},{key:'saturatedFat',label:'Saturadas',unit:'g'},{key:'sodiumMg',label:'Sodio',unit:'mg'}];constructor(private api:ApiService,private route:ActivatedRoute,private router:Router,private snack:MatSnackBar){}ngOnInit(){const id=this.route.snapshot.paramMap.get('id')!;this.api.recipe(id).subscribe(x=>this.detail=x);this.api.recipeVersions(id).subscribe(x=>this.versions=x)}versionLabel(name:string){return name.includes(' · ')?name.split(' · ')[1]:'Original'}versionWeight(v:RecipeSummary){return v.targetWeightPerBar}newVersion(){if(!this.detail)return;const versionName=window.prompt('Nombre de la nueva versión (por ejemplo: Volumen)');if(!versionName?.trim())return;const raw=window.prompt('Peso objetivo por barrita en gramos','85');if(raw===null)return;const weight=Number(raw.replace(',','.'));if(!Number.isFinite(weight)||weight<=0){this.snack.open('Ingresá un peso válido','Cerrar',{duration:3000});return}this.api.createRecipeVersion(this.detail.recipe.id,{versionName:versionName.trim(),targetWeightPerBar:weight}).subscribe({next:x=>this.router.navigate(['/recetas',x.recipe.id]),error:e=>this.snack.open(e.error?.title||'No se pudo crear la versión','Cerrar',{duration:4000})})}costRows(d:any){return[{label:'Ingredientes',value:d.analysis.cost.ingredients},{label:'Merma',value:d.analysis.cost.waste},{label:'Packaging',value:d.analysis.cost.packaging},{label:'Mano de obra',value:d.analysis.cost.labor},{label:'Electricidad y otros',value:d.analysis.cost.electricity+d.analysis.cost.transport+d.analysis.cost.other},{label:'Indirectos',value:d.analysis.cost.indirect}]}}

@Component({standalone:true,imports:UI,template:`
<div class="title-row"><div><a class="back" routerLink="/recetas">Volver a recetas</a><h1>{{id?'Editar receta':'Nueva receta'}}</h1><p>Los resultados se actualizan mientras formulás.</p></div><button mat-flat-button color="primary" (click)="save()" [disabled]="form.invalid||saving||bars<=0">Guardar receta</button></div>
<form [formGroup]="form"><div class="editor-layout"><div>
<mat-card class="panel"><h2>Datos de la receta</h2><div class="fields cols-3"><mat-form-field appearance="outline"><mat-label>Nombre</mat-label><input matInput formControlName="name"></mat-form-field><mat-form-field appearance="outline"><mat-label>Sabor</mat-label><input matInput formControlName="flavor"></mat-form-field><mat-form-field appearance="outline"><mat-label>Barritas producidas</mat-label><input matInput type="number" [value]="bars" readonly><mat-hint>Peso total ÷ peso objetivo</mat-hint></mat-form-field><mat-form-field appearance="outline"><mat-label>Peso objetivo / barra</mat-label><input matInput type="number" formControlName="targetWeightPerBar"></mat-form-field><mat-form-field appearance="outline"><mat-label>Proteína objetivo / barra</mat-label><input matInput type="number" formControlName="targetProteinPerBar"></mat-form-field><mat-form-field appearance="outline"><mat-label>Peso final calculado</mat-label><input matInput type="number" [value]="totalWeight" readonly><span matSuffix>g</span><mat-hint>Suma de los ingredientes</mat-hint></mat-form-field></div><div class="checks"><mat-checkbox formControlName="keto">Keto</mat-checkbox><mat-checkbox formControlName="sugarFree">Sin azúcar</mat-checkbox><mat-checkbox formControlName="vegan">Vegana</mat-checkbox><mat-checkbox formControlName="active">Activa</mat-checkbox></div></mat-card>
<mat-card class="panel"><div class="panel-head"><div><h2>Ingredientes</h2><p>Ordenados alfabéticamente por nombre.</p></div><button mat-stroked-button type="button" (click)="addLine()">Agregar ingrediente</button></div><div formArrayName="ingredients" class="editor-lines"><div class="editor-line" *ngFor="let row of lines.controls;let i=index" [formGroupName]="i"><app-search-select class="grow" label="Ingrediente" placeholder="Buscar ingrediente..." [options]="ingredients" valueKey="id" labelKey="name" formControlName="ingredientId" (valueChange)="sortLines()"/><mat-form-field appearance="outline"><mat-label>Cantidad</mat-label><input matInput type="number" formControlName="quantity"></mat-form-field><app-search-select label="Unidad" [options]="units" formControlName="unit"/><app-search-select class="section-select" label="Sección" [options]="sections" formControlName="section"/><div class="line-calc"><small>Costo</small><b>{{currency(lineCost(i))}}</b></div><div class="line-calc"><small>Proteína</small><b>{{lineProtein(i)|number:'1.1-1'}} g</b></div><button mat-button type="button" (click)="lines.removeAt(i)">Quitar</button></div></div></mat-card>
<mat-card class="panel"><h2>Costos y precios</h2><div class="fields cols-3"><mat-form-field appearance="outline"><mat-label>Merma %</mat-label><input matInput type="number" formControlName="wastePercent"></mat-form-field><mat-form-field appearance="outline"><mat-label>Envase / barra</mat-label><input matInput type="number" formControlName="packageCostPerBar"></mat-form-field><mat-form-field appearance="outline"><mat-label>Etiqueta / barra</mat-label><input matInput type="number" formControlName="labelCostPerBar"></mat-form-field><mat-form-field appearance="outline"><mat-label>Mano de obra / lote</mat-label><input matInput type="number" formControlName="laborPerBatch"></mat-form-field><mat-form-field appearance="outline"><mat-label>Electricidad / lote</mat-label><input matInput type="number" formControlName="electricityPerBatch"></mat-form-field><mat-form-field appearance="outline"><mat-label>Indirectos %</mat-label><input matInput type="number" formControlName="indirectCostsPercent"></mat-form-field><mat-form-field appearance="outline"><mat-label>Venta directa</mat-label><input matInput type="number" formControlName="directPrice"></mat-form-field><mat-form-field appearance="outline"><mat-label>Precio gimnasio</mat-label><input matInput type="number" formControlName="gymPrice"></mat-form-field><mat-form-field appearance="outline"><mat-label>Mayorista</mat-label><input matInput type="number" formControlName="wholesalePrice"></mat-form-field></div></mat-card></div>
<aside class="live-panel"><p class="eyebrow">RESULTADO EN VIVO</p><h2>{{form.value.name||'Nueva receta'}}</h2><div class="live-main"><small>COSTO POR BARRA</small><strong>{{currency(totalCost/bars)}}</strong></div><div class="live-stat"><span>Proteína por barra</span><b>{{nutrientPerBar('protein')|number:'1.1-1'}} g</b></div><div class="live-stat"><span>Carbohidratos por barra</span><b>{{nutrientPerBar('carbohydrates')|number:'1.1-1'}} g</b></div><div class="live-stat"><span>Grasas por barra</span><b>{{nutrientPerBar('totalFat')|number:'1.1-1'}} g</b></div><div class="live-stat"><span>Fibra por barra</span><b>{{nutrientPerBar('fiber')|number:'1.1-1'}} g</b></div><div class="live-stat"><span>Calorías por barra</span><b>{{nutrientPerBar('kcal')|number:'1.0-0'}} kcal</b></div><div class="live-stat"><span>Peso de la barrita</span><b>{{barWeight|number:'1.0-1'}} g</b></div><div class="live-stat"><span>Peso usado del lote</span><b>{{usedWeight|number:'1.0-1'}} g</b></div><div class="live-stat"><span>Margen gimnasio</span><b>{{margin|number:'1.1-1'}}%</b></div><div class="goal" [class.ok]="nutrientPerBar('protein')>=(form.value.targetProteinPerBar||0)"><span>Objetivo de proteína<b>{{nutrientPerBar('protein')|number:'1.1-1'}} / {{form.value.targetProteinPerBar}} g</b></span></div><small class="truth">La nutrición se calcula según el peso configurado de la barrita y la concentración del lote.</small></aside></div></form>`})
export class RecipeFormComponent implements OnInit {id='';saving=false;ingredients:Ingredient[]=[];units=['G','Kg','Ml','L','Unit'];sections=['Dry','Wet','Inclusions','Filling','Coating','Decoration','Other'];currency=money;form=this.fb.group({name:['',Validators.required],description:[''],flavor:[''],category:['Barrita proteica'],keto:[false],sugarFree:[false],vegan:[false],active:[true],expectedBars:[12,[Validators.required,Validators.min(1)]],targetWeightPerBar:[60,[Validators.required,Validators.min(.01)]],finalBatchWeight:[null as number|null],targetProteinPerBar:[20],wastePercent:[3],packageCostPerBar:[2],labelCostPerBar:[1],laborPerBatch:[24],electricityPerBatch:[10],transportPerBatch:[0],otherCostsPerBatch:[0],indirectCostsPercent:[5],notes:[''],directPrice:[120],gymPrice:[90],wholesalePrice:[80],ingredients:this.fb.array([])});constructor(private fb:FormBuilder,private api:ApiService,private route:ActivatedRoute,private router:Router,private snack:MatSnackBar){}get lines(){return this.form.controls.ingredients as FormArray}ngOnInit(){this.id=this.route.snapshot.paramMap.get('id')||'';this.api.ingredients().subscribe(xs=>{this.ingredients=xs.sort((a,b)=>a.name.localeCompare(b.name,'es'));if(this.id)this.api.recipe(this.id).subscribe(d=>this.load(d));else this.addLine()})}addLine(v?:any){this.lines.push(this.fb.group({ingredientId:[v?.ingredientId||'',Validators.required],quantity:[v?.quantity??10,[Validators.required,Validators.min(.01)]],unit:[v?.unit||'G'],section:[v?.section||'Dry'],optional:[v?.optional||false],observation:[v?.observation||'']}))}load(d:RecipeDetail){const r=d.recipe;this.form.patchValue({...r,directPrice:r.salePrices?.find((p:any)=>p.channel==='Direct')?.price||0,gymPrice:r.salePrices?.find((p:any)=>p.channel==='Gym')?.price||0,wholesalePrice:r.salePrices?.find((p:any)=>p.channel==='Wholesale')?.price||0});this.lines.clear();r.ingredients.forEach((x:any)=>this.addLine(x));this.sortLines()}sortLines(){setTimeout(()=>{const controls=[...this.lines.controls].sort((a,b)=>{const an=this.ingredients.find(x=>x.id===a.value.ingredientId)?.name||'ZZZ';const bn=this.ingredients.find(x=>x.id===b.value.ingredientId)?.name||'ZZZ';return an.localeCompare(bn,'es')});if(controls.every((control,index)=>control===this.lines.at(index)))return;this.lines.clear({emitEvent:false});controls.forEach(control=>this.lines.push(control,{emitEvent:false}))})}ingredientAt(i:number){return this.ingredients.find(x=>x.id===this.lines.at(i).value.ingredientId)}baseQty(i:number){const row=this.lines.at(i).value,x=this.ingredientAt(i);if(!x)return 0;let q=+row.quantity||0;if(row.unit==='Kg')q*=1000;if(row.unit==='L')q*=1000;if(row.unit==='G'&&x.baseUnit==='Ml')q/=x.densityGPerMl||1;if(row.unit==='Ml'&&x.baseUnit==='G')q*=x.densityGPerMl||0;return q}gramsQty(i:number){const row=this.lines.at(i).value,x=this.ingredientAt(i);if(!x)return 0;let q=+row.quantity||0;if(row.unit==='Kg')return q*1000;if(row.unit==='G')return q;if(row.unit==='L')q*=1000;if(row.unit==='Ml')return q*(x.densityGPerMl||0);return x.baseUnit==='G'?q:0}lineCost(i:number){const x=this.ingredientAt(i);return x?this.baseQty(i)*x.costPerBaseUnit:0}lineNutrient(i:number,key:keyof Ingredient['nutrition']){const x=this.ingredientAt(i);const value=x?.nutrition[key];return x&&typeof value==='number'?this.gramsQty(i)/100*value:0}lineProtein(i:number){return this.lineNutrient(i,'protein')}get ingredientCost(){return this.lines.controls.reduce((s,_,i)=>s+this.lineCost(i),0)}get totalWeight(){return this.lines.controls.reduce((s,_,i)=>s+this.gramsQty(i),0)}nutrientTotal(key:keyof Ingredient['nutrition']){return this.lines.controls.reduce((s,_,i)=>s+this.lineNutrient(i,key),0)}get usedWeight(){return this.totalWeight}get barWeight(){return Math.max(0,+(this.form.value.targetWeightPerBar||0))}nutrientPerBar(key:keyof Ingredient['nutrition']){return this.usedWeight>0?this.nutrientTotal(key)/this.usedWeight*this.barWeight:0}get bars(){return this.barWeight>0?Math.max(0,Math.floor(this.totalWeight/this.barWeight)):0}get totalCost(){const f=this.form.value;const ingredientsWithWaste=this.ingredientCost*(1+(+f.wastePercent!||0)/100);const direct=ingredientsWithWaste+this.bars*((+f.packageCostPerBar!||0)+(+f.labelCostPerBar!||0))+(+f.laborPerBatch!||0)+(+f.electricityPerBatch!||0)+(+f.transportPerBatch!||0)+(+f.otherCostsPerBatch!||0);return direct*(1+(+f.indirectCostsPercent!||0)/100)}get margin(){const price=+(this.form.value.gymPrice||0),cost=this.bars>0?this.totalCost/this.bars:0;return price?(price-cost)/price*100:0}save(){if(this.form.invalid||this.bars<=0)return;const v:any=this.form.getRawValue();const payload={...v,expectedBars:this.bars,finalBatchWeight:this.totalWeight,ingredients:v.ingredients,salePrices:[{channel:'Direct',price:v.directPrice},{channel:'Gym',price:v.gymPrice},{channel:'Wholesale',price:v.wholesalePrice}]};delete payload.directPrice;delete payload.gymPrice;delete payload.wholesalePrice;this.saving=true;this.api.saveRecipe(payload,this.id||undefined).subscribe({next:d=>{this.snack.open('Receta guardada','Cerrar',{duration:2500});this.router.navigate(['/recetas',d.recipe.id])},error:e=>{this.saving=false;this.snack.open(e.error?.title||'No se pudo guardar','Cerrar')}})}}

@Component({standalone:true,imports:UI,template:`
<div class="title-row"><div><p class="eyebrow">ANÁLISIS</p><h1>Comparar recetas</h1><p>Elegí entre 2 y 4 formulaciones.</p></div><button mat-flat-button color="primary" (click)="compare()" [disabled]="selected.length<2">Comparar</button></div><mat-card class="panel"><app-search-select label="Recetas" placeholder="Buscar receta..." [options]="recipes" valueKey="id" labelKey="name" [multiple]="true" [value]="selected" (valueChange)="selected=$event"/></mat-card><div class="compare-grid" *ngIf="details.length"><mat-card class="compare-card" *ngFor="let d of details"><span class="tag">{{d.recipe.category}}</span><h2>{{d.recipe.name}}</h2><div *ngFor="let x of rows"><span>{{x.label}}</span><b>{{value(d,x)|number:'1.1-1'}} {{x.unit}}</b></div></mat-card></div>`})
export class CompareComponent implements OnInit {recipes:RecipeSummary[]=[];selected:string[]=[];details:RecipeDetail[]=[];rows=[{label:'Peso por barra',path:'recipe.targetWeightPerBar',unit:'g'},{label:'Calorías',path:'analysis.perBar.kcal',unit:'kcal'},{label:'Proteína',path:'analysis.perBar.protein',unit:'g'},{label:'Carbohidratos',path:'analysis.perBar.carbohydrates',unit:'g'},{label:'Azúcares',path:'analysis.perBar.sugars',unit:'g'},{label:'Grasas',path:'analysis.perBar.totalFat',unit:'g'},{label:'Costo',path:'analysis.cost.perBar',unit:'$'}];constructor(private api:ApiService){}ngOnInit(){this.api.recipes().subscribe(x=>this.recipes=x)}compare(){this.api.compare(this.selected.slice(0,4)).subscribe(x=>this.details=x)}value(d:any,row:any){return row.path.split('.').reduce((o:any,k:string)=>o?.[k],d)||0}}

@Component({standalone:true,imports:UI,template:`
<div class="title-row"><div><p class="eyebrow">TRAZABILIDAD</p><h1>Producción</h1><p>Cada lote conserva sus costos históricos.</p></div></div><div class="grid-2"><mat-card class="panel"><h2>Registrar lote</h2><form [formGroup]="form" class="fields"><app-search-select label="Receta" placeholder="Buscar receta..." [options]="recipes" valueKey="id" labelKey="name" formControlName="recipeId"/><mat-form-field appearance="outline"><mat-label>Cantidad de tandas</mat-label><input matInput type="number" formControlName="batches"></mat-form-field><mat-form-field appearance="outline"><mat-label>Barras esperadas</mat-label><input matInput type="number" formControlName="expectedBars"></mat-form-field><mat-form-field appearance="outline"><mat-label>Barras producidas</mat-label><input matInput type="number" formControlName="actualBars"></mat-form-field><mat-form-field appearance="outline"><mat-label>Descartadas</mat-label><input matInput type="number" formControlName="discardedBars"></mat-form-field><mat-form-field appearance="outline"><mat-label>Peso final real (g)</mat-label><input matInput type="number" formControlName="actualWeight"></mat-form-field><mat-checkbox formControlName="deductStock">Descontar ingredientes del stock</mat-checkbox><button mat-flat-button color="primary" (click)="create()">Registrar lote</button></form></mat-card><mat-card class="panel"><h2>Últimos lotes</h2><div class="line" *ngFor="let b of batches"><div><b>{{b.recipeName}}</b><small>{{b.producedAt|date:'dd/MM/yyyy'}} · {{b.actualBars}} barras buenas</small></div><div class="right"><b>{{currency(b.costPerGoodBar)}} / barra</b><small>{{b.wastePercent|number:'1.1-1'}}% merma</small></div></div><div class="empty" *ngIf="!batches.length">Todavía no registraste lotes.</div></mat-card></div>`})
export class ProductionComponent implements OnInit {recipes:RecipeSummary[]=[];batches:Batch[]=[];currency=money;form=this.fb.group({recipeId:['',Validators.required],batches:[1],expectedBars:[12],actualBars:[12,Validators.min(1)],discardedBars:[0],actualWeight:[700],deductStock:[false],notes:['']});constructor(private fb:FormBuilder,private api:ApiService,private snack:MatSnackBar){}ngOnInit(){this.api.recipes().subscribe(x=>this.recipes=x);this.load()}load(){this.api.batches().subscribe(x=>this.batches=x)}create(){if(this.form.invalid)return;this.api.createBatch(this.form.getRawValue()).subscribe(()=>{this.snack.open('Lote registrado','Cerrar',{duration:2000});this.load()})}}

@Component({standalone:true,imports:UI,template:`
<div class="title-row"><div><p class="eyebrow">RENTABILIDAD REAL</p><h1>Registro de ventas</h1><p>Registrá unidades vendidas y compará ingresos contra el costo de producción.</p></div></div>
<div class="metrics sales-metrics" *ngIf="summary as s"><article><small>INGRESOS</small><strong>{{currency(s.revenue)}}</strong><em>{{s.units}} unidades vendidas</em></article><article><small>COSTO</small><strong>{{currency(s.cost)}}</strong><em>Costo histórico registrado</em></article><article><small>GANANCIA</small><strong>{{currency(s.profit)}}</strong><em>Ingresos menos costos</em></article><article><small>MARGEN</small><strong>{{s.marginPercent|number:'1.1-1'}}%</strong><em>{{s.salesCount}} operaciones</em></article></div>
<mat-card class="panel customer-form" *ngIf="showCustomerForm"><div class="panel-head"><div><h2>Nuevo cliente</h2><p>Guardá sus datos para asociar ventas y consultar su rentabilidad.</p></div><button mat-button type="button" (click)="cancelCustomer()">Cancelar</button></div><form [formGroup]="customerForm" class="fields customer-fields"><mat-form-field appearance="outline"><mat-label>Nombre o empresa</mat-label><input matInput formControlName="name" autocomplete="name"><mat-error>El nombre es obligatorio</mat-error></mat-form-field><mat-form-field appearance="outline"><mat-label>Teléfono</mat-label><input matInput formControlName="phone" autocomplete="tel" placeholder="Ej.: 099 123 456"></mat-form-field><mat-form-field appearance="outline"><mat-label>Notas</mat-label><input matInput formControlName="notes" placeholder="Gimnasio, entrega, contacto..."></mat-form-field></form><div class="customer-actions"><small>Quedará seleccionado automáticamente en la venta actual.</small><button mat-flat-button color="primary" type="button" (click)="createCustomer()" [disabled]="customerForm.invalid||savingCustomer">{{savingCustomer?'Guardando...':'Guardar cliente'}}</button></div></mat-card>
<div class="grid-2"><mat-card class="panel"><div class="panel-head"><h2>Nueva venta</h2><button mat-stroked-button type="button" (click)="openCustomerForm()">Nuevo cliente</button></div><form [formGroup]="form"><div class="fields cols-2"><app-search-select class="span-2" label="Cliente" placeholder="Buscar cliente..." [options]="summary?.customers||[]" valueKey="id" labelKey="name" formControlName="customerId"/><app-search-select label="Canal" [options]="channels" formControlName="channel"/><mat-form-field appearance="outline"><mat-label>Fecha</mat-label><input matInput type="datetime-local" formControlName="soldAt"></mat-form-field></div><div formArrayName="lines" class="sale-products"><div class="sale-product" *ngFor="let row of saleLines.controls;let i=index" [formGroupName]="i"><app-search-select label="Producto" [options]="recipes" valueKey="id" labelKey="name" formControlName="recipeId" (valueChange)="selectProduct(i,$event)"/><mat-form-field appearance="outline"><mat-label>Cantidad</mat-label><input matInput type="number" formControlName="quantity"></mat-form-field><mat-form-field appearance="outline"><mat-label>Precio unitario</mat-label><input matInput type="number" formControlName="unitPrice"></mat-form-field><button mat-button class="danger" type="button" (click)="removeProduct(i)" [disabled]="saleLines.length===1">Quitar</button></div></div><button mat-stroked-button type="button" (click)="addProduct()">Agregar producto</button><mat-form-field appearance="outline" class="wide sale-notes"><mat-label>Notas</mat-label><textarea matInput formControlName="notes"></textarea></mat-form-field></form><div class="sale-preview"><span>Ingreso <b>{{currency(previewRevenue)}}</b></span><span>Costo <b>{{currency(previewCost)}}</b></span><span>Ganancia estimada <b>{{currency(previewProfit)}}</b></span></div><button mat-flat-button color="primary" (click)="create()" [disabled]="form.invalid||saving">Registrar venta completa</button></mat-card>
<mat-card class="panel"><div class="panel-head"><div><h2>Últimas ventas</h2><p>El costo queda congelado al momento de registrar.</p></div></div><div class="line sale-line" *ngFor="let x of summary?.sales"><div><b>{{x.recipeName}}</b><small>{{x.customerName||'Sin cliente'}} · {{x.soldAt|date:'dd/MM/yyyy HH:mm'}} · {{x.quantity}} unidades · {{x.channel||'Sin canal'}}</small></div><div class="right"><b [class.negative]="x.profit<0">{{currency(x.profit)}}</b><small>{{currency(x.revenue)}} ingreso · {{x.marginPercent|number:'1.1-1'}}%</small></div><button mat-button class="danger" type="button" (click)="remove(x.id)">Eliminar</button></div><div class="empty" *ngIf="!summary?.sales?.length">Todavía no registraste ventas.</div></mat-card></div>
<mat-card class="panel"><div class="panel-head"><div><h2>Estadísticas por cliente</h2><p>Actividad y rentabilidad acumulada.</p></div><button mat-stroked-button type="button" (click)="openCustomerForm()">Crear cliente</button></div><div class="table-wrap"><table><thead><tr><th>CLIENTE</th><th>BARRAS</th><th>VENTAS</th><th>FACTURACIÓN</th><th>COSTO</th><th>GANANCIA</th><th>MARGEN</th><th></th></tr></thead><tbody><tr *ngFor="let c of summary?.customers"><td><b>{{c.name}}</b><small>{{c.phone||c.notes||'Sin datos adicionales'}}</small></td><td>{{c.units}}</td><td>{{c.salesCount}}</td><td>{{currency(c.revenue)}}</td><td>{{currency(c.cost)}}</td><td><b [class.negative]="c.profit<0">{{currency(c.profit)}}</b></td><td>{{c.marginPercent|number:'1.1-1'}}%</td><td><button mat-button (click)="viewCustomer(c.id)">Ver historial</button></td></tr></tbody></table><div class="empty" *ngIf="!summary?.customers?.length">Creá tu primer cliente para comenzar a registrar sus estadísticas.</div></div></mat-card>
<mat-card class="panel customer-history" *ngIf="customerDetail as d"><div class="panel-head"><div><p class="eyebrow">HISTORIAL DEL CLIENTE</p><h2>{{d.customer.name}}</h2><p>{{d.customer.units}} barras · {{d.customer.salesCount}} ventas · {{currency(d.customer.profit)}} de ganancia</p></div><button mat-button (click)="customerDetail=undefined">Cerrar</button></div><article class="order-card" *ngFor="let order of d.orders"><div class="order-head"><div><b>{{order.soldAt|date:'dd/MM/yyyy HH:mm'}}</b><small>{{order.channel||'Sin canal'}} · {{order.units}} unidades</small></div><div class="right"><b>{{currency(order.profit)}} ganancia</b><small>{{currency(order.revenue)}} facturado</small></div></div><div class="order-line" *ngFor="let line of order.lines"><span>{{line.recipeName}}</span><span>{{line.quantity}} × {{currency(line.unitPrice)}}</span><b>{{currency(line.revenue)}}</b></div><p *ngIf="order.notes">{{order.notes}}</p></article><div class="empty" *ngIf="!d.orders.length">Este cliente todavía no tiene ventas.</div></mat-card>`})
export class SalesComponent implements OnInit {recipes:RecipeSummary[]=[];summary?:SalesSummary;customerDetail?:CustomerDetail;saving=false;showCustomerForm=false;savingCustomer=false;channels=['Directo','Gimnasio','Mayorista','Promocional','Otro'];currency=money;customerForm=this.fb.group({name:['',Validators.required],phone:[''],notes:['']});form=this.fb.group({customerId:[null as string|null],soldAt:[this.localDateTime()],channel:['Directo'],notes:[''],lines:this.fb.array([])});constructor(private fb:FormBuilder,private api:ApiService,private snack:MatSnackBar){this.addProduct()}get saleLines(){return this.form.controls.lines as FormArray}ngOnInit(){this.api.recipes().subscribe(x=>this.recipes=x.filter(r=>r.active).sort((a,b)=>a.name.localeCompare(b.name,'es')));this.load()}load(){this.api.sales().subscribe(x=>this.summary=x)}addProduct(){this.saleLines.push(this.fb.group({recipeId:['',Validators.required],quantity:[1,[Validators.required,Validators.min(1)]],unitPrice:[0,[Validators.required,Validators.min(0)]]}))}removeProduct(i:number){if(this.saleLines.length>1)this.saleLines.removeAt(i)}selectProduct(i:number,id:string){const r=this.recipes.find(x=>x.id===id);if(r)this.saleLines.at(i).patchValue({unitPrice:r.directPrice||r.gymPrice||0})}get previewRevenue(){return this.saleLines.controls.reduce((s,x)=>s+(+x.value.quantity||0)*(+x.value.unitPrice||0),0)}get previewCost(){return this.saleLines.controls.reduce((s,x)=>s+(+x.value.quantity||0)*(this.recipes.find(r=>r.id===x.value.recipeId)?.costPerBar||0),0)}get previewProfit(){return this.previewRevenue-this.previewCost}create(){if(this.form.invalid)return;this.saving=true;this.api.createSaleOrder(this.form.getRawValue()).subscribe({next:()=>{this.saving=false;this.form.patchValue({notes:'',soldAt:this.localDateTime()});this.saleLines.clear();this.addProduct();this.snack.open('Venta registrada','Cerrar',{duration:2200});this.load()},error:e=>{this.saving=false;this.snack.open(e.error?.title||'No se pudo registrar la venta','Cerrar',{duration:4000})}})}openCustomerForm(){this.showCustomerForm=true;setTimeout(()=>document.querySelector<HTMLInputElement>('.customer-form input')?.focus())}cancelCustomer(){this.showCustomerForm=false;this.customerForm.reset({name:'',phone:'',notes:''})}createCustomer(){if(this.customerForm.invalid)return;this.savingCustomer=true;this.api.createCustomer(this.customerForm.getRawValue()).subscribe({next:c=>{this.savingCustomer=false;this.showCustomerForm=false;this.customerForm.reset({name:'',phone:'',notes:''});this.form.patchValue({customerId:c.id});this.load();this.snack.open('Cliente creado y seleccionado','Cerrar',{duration:2200})},error:e=>{this.savingCustomer=false;this.snack.open(e.error?.title||'No se pudo crear el cliente','Cerrar',{duration:4000})}})}viewCustomer(id:string){this.api.customerDetail(id).subscribe(x=>{this.customerDetail=x;setTimeout(()=>document.querySelector('.customer-history')?.scrollIntoView({behavior:'smooth'}))})}remove(id:string){if(!window.confirm('¿Eliminar esta venta?'))return;this.api.deleteSale(id).subscribe(()=>{this.customerDetail=undefined;this.load()})}private localDateTime(){const d=new Date(Date.now()-new Date().getTimezoneOffset()*60000);return d.toISOString().slice(0,16)}}

@Component({standalone:true,imports:UI,template:`
<div class="title-row"><div><p class="eyebrow">PROYECCIONES</p><h1>Simulador de ventas</h1><p>Combiná canales y frecuencias de venta.</p></div><button mat-flat-button color="primary" (click)="calculate()">Calcular proyección</button></div><div class="grid-2"><mat-card class="panel"><div class="panel-head"><h2>Canales</h2><button mat-stroked-button (click)="add()">Agregar canal</button></div><div [formGroup]="form"><div formArrayName="lines"><div class="sim-line" *ngFor="let x of lines.controls;let i=index" [formGroupName]="i"><mat-form-field appearance="outline"><mat-label>Canal</mat-label><input matInput formControlName="label"></mat-form-field><mat-form-field appearance="outline"><mat-label>Barras/día</mat-label><input matInput type="number" formControlName="unitsPerDay"></mat-form-field><mat-form-field appearance="outline"><mat-label>Días/semana</mat-label><input matInput type="number" formControlName="daysPerWeek"></mat-form-field><mat-form-field appearance="outline"><mat-label>Precio</mat-label><input matInput type="number" formControlName="price"></mat-form-field><mat-form-field appearance="outline"><mat-label>Costo</mat-label><input matInput type="number" formControlName="cost"></mat-form-field></div></div></div></mat-card><mat-card class="panel projection" *ngIf="result"><p class="eyebrow">RESULTADO ESTIMADO</p><div><span>Ganancia diaria</span><b>{{currency(result.dailyProfit)}}</b></div><div><span>Ganancia semanal</span><b>{{currency(result.weeklyProfit)}}</b></div><div><span>Ganancia mensual</span><b>{{currency(result.monthlyProfit)}}</b></div><div class="annual"><span>PROYECCIÓN ANUAL</span><strong>{{currency(result.annualProfit)}}</strong><small>{{currency(result.annualRevenue)}} de facturación</small></div></mat-card></div>`})
export class SimulatorComponent {currency=money;result:any;form=this.fb.group({lines:this.fb.array([])});constructor(private fb:FormBuilder,private api:ApiService){this.add('Gimnasios',50,6,90,42);this.add('Venta directa',12,1,120,42)}get lines(){return this.form.controls.lines as FormArray}add(label='Nuevo canal',units=10,days=5,price=90,cost=42){this.lines.push(this.fb.group({label:[label],unitsPerDay:[units],daysPerWeek:[days],price:[price],cost:[cost]}))}calculate(){this.api.simulate(this.lines.getRawValue()).subscribe(x=>this.result=x)}}

@Component({standalone:true,imports:UI,template:`<div class="title-row"><div><p class="eyebrow">PREFERENCIAS</p><h1>Configuración</h1><p>Valores predeterminados para nuevas recetas.</p></div><button mat-flat-button color="primary" (click)="save()">Guardar configuración</button></div><mat-card class="panel settings"><h2>Parámetros del negocio</h2><p>Estos valores quedan persistidos en PostgreSQL.</p><form [formGroup]="form" class="fields cols-3"><mat-form-field appearance="outline"><mat-label>Moneda</mat-label><input matInput formControlName="currency"></mat-form-field><mat-form-field appearance="outline"><mat-label>IVA predeterminado %</mat-label><input matInput type="number" formControlName="defaultVat"></mat-form-field><mat-form-field appearance="outline"><mat-label>Margen mínimo %</mat-label><input matInput type="number" formControlName="minimumMargin"></mat-form-field><mat-form-field appearance="outline"><mat-label>Proteína objetivo g</mat-label><input matInput type="number" formControlName="defaultProteinTarget"></mat-form-field><mat-form-field appearance="outline"><mat-label>Merma %</mat-label><input matInput type="number" formControlName="defaultWastePercent"></mat-form-field><mat-form-field appearance="outline"><mat-label>Costo envase</mat-label><input matInput type="number" formControlName="defaultPackageCost"></mat-form-field><mat-form-field appearance="outline"><mat-label>Costo etiqueta</mat-label><input matInput type="number" formControlName="defaultLabelCost"></mat-form-field><mat-form-field appearance="outline"><mat-label>Costo hora</mat-label><input matInput type="number" formControlName="hourlyLaborCost"></mat-form-field><mat-form-field appearance="outline"><mat-label>Electricidad estimada</mat-label><input matInput type="number" formControlName="estimatedElectricityCost"></mat-form-field></form></mat-card>`})
export class SettingsComponent implements OnInit {form=this.fb.group({id:[1],currency:['UYU'],defaultVat:[22],minimumMargin:[30],defaultProteinTarget:[20],defaultWastePercent:[3],defaultPackageCost:[2],defaultLabelCost:[1],hourlyLaborCost:[0],estimatedElectricityCost:[0]});constructor(private fb:FormBuilder,private api:ApiService,private snack:MatSnackBar){}ngOnInit(){this.api.settings().subscribe(x=>this.form.patchValue(x))}save(){this.api.saveSettings(this.form.getRawValue()).subscribe(()=>this.snack.open('Configuración guardada','Cerrar',{duration:2200}))}}
